t=document.createElement("div");Object.assign(t.style,{position:"fixed",inset:"0",background:"rgba(0,0,0,0.6)",zIndex:"99999"});const e=document.createElement("div");Object.assign(e.style,{position:"fixed",top:"50%",left:"50%",transform:"translate(-50%, -50%)",background:"rgba(8, 8, 20, 0.98)",border:"1px solid rgba(180, 140, 255, 0.3)",borderRadius:"10px",padding:"20px",zIndex:"100000",width:"480px",maxWidth:"90vw",maxHeight:"80vh",display:"flex",flexDirection:"column",boxShadow:"0 8px 40px rgba(0,0,0,0.8)"});const n=document.createElement("div");n.textContent="🔗 Glass Ledger",Object.assign(n.style,{color:"#b48cff",fontSize:"14px",fontWeight:"600",marginBottom:"4px"}),e.appendChild(n);const i=document.createElement("div");i.textContent="A hash-chained, tamper-evident record of trade fills and indicator saves/deletes.",Object.assign(i.style,{color:"rgba(255,255,255,0.4)",fontSize:"10px",marginBottom:"10px"}),e.appendChild(i);const a=document.createElement("div");Object.assign(a.style,{display:"flex",alignItems:"center",gap:"8px",marginBottom:"10px"});const o=document.createElement("button");o.textContent="✓ Verify Integrity",Object.assign(o.style,{padding:"5px 12px",border:"1px solid rgba(34,204,136,0.4)",borderRadius:"4px",background:"rgba(34,204,136,0.12)",color:"#22cc88",cursor:"pointer",fontSize:"11px",fontWeight:"600"});const r=document.createElement("span");Object.assign(r.style,{fontSize:"10px",color:"rgba(255,255,255,0.5)"}),o.onclick=async()=>{o.disabled=!0,r.textContent="Verifying...",r.style.color="rgba(255,255,255,0.5)";const d=await jC();d.ok?(r.textContent=d.checkedCount===0?"Ledger is empty.":`✓ Chain intact — ${d.checkedCount} entries verified.${d.prunedBefore?" (Oldest entries have been pruned; verified from the oldest entry still stored.)":""}`,r.style.color=ql().bull):(r.textContent=`✗ BROKEN at entry ${d.brokenAtSeq}: ${d.reason}`,r.style.color=ql().bear),o.disabled=!1},a.appendChild(o),a.appendChild(r),e.appendChild(a);const s=document.createEle